-- -- propagate to existing variants -----------------------------------
-- Variants inherit the category through INSERT ... SELECT * only when they
-- are regenerated.  The entry encodes the base (ItemUpgrade.h), so one
-- statement brings an existing band up to date instead -- far cheaper than
-- regenerating ~78k rows to move one column.
UPDATE `item_template` v
  JOIN `item_template` b ON b.`entry` = (v.`entry` - 1000000) DIV 20
  SET v.`ItemLimitCategory` = b.`ItemLimitCategory`
WHERE v.`entry` >= 1000000;

